package com.smartbus.auth.service;
import com.smartbus.auth.dto.*; import com.smartbus.auth.entity.*; import com.smartbus.auth.repository.*; import jakarta.transaction.Transactional; import java.time.Instant; import java.util.*; import org.springframework.stereotype.Service;
@Service public class QrAuthService { private final LoginQrTokenRepository tokens; public QrAuthService(LoginQrTokenRepository tokens){this.tokens=tokens;} @Transactional public AuthResponse login(QrLoginRequest request){ UUID value; try{value=UUID.fromString(request.token());}catch(IllegalArgumentException e){throw new IllegalArgumentException("Invalid login QR");} LoginQrToken qr=tokens.findByToken(value).orElseThrow(()->new IllegalArgumentException("Invalid login QR")); if(qr.used) throw new IllegalStateException("This login QR has already been used"); if(!"ACTIVE".equals(qr.student.status)||!qr.student.telegramEnabled) throw new IllegalStateException("Student access is disabled"); qr.used=true; qr.usedAt=Instant.now(); /* Deactivate prior session, persist the new session, and sign JWT here. */ return new AuthResponse("replace-with-signed-jwt",new AuthResponse.StudentProfile(qr.student.name,qr.student.rollNo,qr.student.department)); } }
